commit 26d0c1edfbdf0420edc2695c0e37014f424a4f28
Author: Marcus Kamuntu <home@aspekts.dev>
Date:   Sat Nov 7 22:30:44 2026 +0000

    Never pass an exam that asked no questions

    A plan with no questions, or only questions about claims it wasn't
    given, made worst-wins default to endorse, recording exam-passed for a
    risky push. Such a plan is now a pipeline failure, so the hook fails
    open with a warning and nothing is recorded. Grading an empty exam
    throws as a second guard. Found in independent review of #7.

    Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>
    Entire-Checkpoint: 01M6W25DG9VX1PV1QV7Y4PQTFR

diff --git a/packages/engine/src/pipeline/aggregate.ts b/packages/engine/src/pipeline/aggregate.ts
index 90a334d..f8058d0 100644
--- a/packages/engine/src/pipeline/aggregate.ts
+++ b/packages/engine/src/pipeline/aggregate.ts
@@ -2,6 +2,8 @@ import { worstVerdict, type Gate, type Grade } from "@viva/contracts";

 /** Worst wins across every graded question. */
 export function aggregateGrades(grades: Grade[]): Gate {
+  // With nothing graded, worst-wins would default to endorse.
+  if (grades.length === 0) throw new Error("cannot decide an exam with no graded answers");
   const verdict = worstVerdict(grades.map((g) => g.verdict));
   const passed = verdict === "approve" || verdict === "endorse";
   return { verdict, reason: passed ? "exam-passed" : "exam-failed", skippable: true };
diff --git a/packages/engine/src/pipeline/plan.ts b/packages/engine/src/pipeline/plan.ts
index d9c2827..d1165d2 100644
--- a/packages/engine/src/pipeline/plan.ts
+++ b/packages/engine/src/pipeline/plan.ts
@@ -20,5 +20,9 @@ export async function planExam(claims: RankedClaim[], llm: LlmProvider): Promise
     user: untrusted("claims", JSON.stringify(brief)),
     schema: ExamPlan,
   });
-  return value;
+  // A plan with no usable questions would grade as a pass, so it's a pipeline failure.
+  const asked = new Set(brief.map((c) => c.id));
+  const questions = value.questions.filter((q) => asked.has(q.claimId));
+  if (questions.length === 0) throw new Error("exam plan asked about none of the risky claims");
+  return { questions };
 }
